begin;
insert into auth.users(id,raw_user_meta_data) values('10000000-0000-0000-0000-000000000001','{"username":"pair_user_a"}'),('10000000-0000-0000-0000-000000000002','{"username":"pair_user_b"}'),('10000000-0000-0000-0000-000000000003','{"username":"pair_user_c"}');
insert into friendships(user_low,user_high) values('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002'),('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003');
do $$ declare a uuid:='10000000-0000-0000-0000-000000000001';b uuid:='10000000-0000-0000-0000-000000000002';j jsonb;i uuid;begin
 j:=nc_invitation_create(a,'pair_user_b');i:=(j->>'id')::uuid;
 begin perform nc_invitation_create(b,'pair_user_a');raise exception 'Reverse bypass';exception when others then if sqlerrm<>'INVITATION_PENDING' then raise;end if;end;
 begin perform nc_invitation_create(a,'pair_user_b');raise exception 'Duplicate bypass';exception when others then if sqlerrm<>'INVITATION_PENDING' then raise;end if;end;
 perform nc_invitation_create(a,'pair_user_c');
 perform nc_invitation_respond(b,i,false,'UNUSED01');
 if nc_direct_eligibility(a,'pair_user_b')->>'state'<>'cooldown' then raise exception 'Cooldown missing';end if;
 begin perform nc_invitation_create(b,'pair_user_a');raise exception 'Cooldown bypass';exception when others then if sqlerrm<>'INVITATION_COOLDOWN' then raise;end if;end;
 if not exists(select 1 from nc_direct_pairs where user_low=a and user_high=b and cooldown_until>clock_timestamp()+interval '14 minutes') then raise exception 'Cooldown too short';end if;
 update nc_direct_pairs set cooldown_until=clock_timestamp()-interval '1 second' where user_low=a and user_high=b;
 j:=nc_invitation_create(b,'pair_user_a');i:=(j->>'id')::uuid;
 j:=nc_invitation_respond(a,i,true,'PAIRDIR1');
 if j->>'code'<>'PAIRDIR1' then raise exception 'Acceptance failed';end if;
 if (select count(*) from nc_room_identities where room_id=(select id from rooms where code='PAIRDIR1') and account_id in(a,b))<>2 then raise exception 'Both memberships missing';end if;
 insert into messages(room_id,sender_id,sender_name,type,content) select room_id,sender_id,alias,'text','isolated fixture' from nc_room_identities where room_id=(select id from rooms where code='PAIRDIR1') and account_id=a;
 if (select count(*) from messages where room_id=(select id from rooms where code='PAIRDIR1'))<>1 then raise exception 'Active message persistence failed';end if;
 if nc_direct_eligibility(b,'pair_user_a')->>'state'<>'active' then raise exception 'Active restriction missing';end if;
 begin perform nc_invitation_create(a,'pair_user_b');raise exception 'Active bypass';exception when others then if sqlerrm<>'ACTIVE_DIRECT_ROOM' then raise;end if;end;
 begin perform nc_invitation_respond(a,i,true,'PAIRDIR2');raise exception 'Acceptance reused';exception when others then if sqlerrm<>'INVITATION_EXPIRED' then raise;end if;end;
 select id into i from rooms where code='PAIRDIR1';delete from rooms where code='PAIRDIR1';
 if exists(select 1 from messages where room_id=i) or exists(select 1 from nc_room_identities where room_id=i) then raise exception 'Conversation cleanup failed';end if;
 if nc_direct_eligibility(a,'pair_user_b')->>'state'<>'available' then raise exception 'Termination did not release';end if;
 j:=nc_invitation_create(a,'pair_user_b');update nc_invitations set expires_at=clock_timestamp()-interval '1 second' where id=(j->>'id')::uuid;
 begin perform nc_invitation_respond(b,(j->>'id')::uuid,true,'PAIRDIR3');raise exception 'Expiry bypass';exception when others then if sqlerrm<>'INVITATION_EXPIRED' then raise;end if;end;
 perform nc_invitation_create(b,'pair_user_a');
 raise notice 'PASS pair pending/reverse/unrelated/cooldown/acceptance/termination/expiry';
end $$;
rollback;
